99: /* Load an image from a file */
100: SDL_Surface *IMG_Load(const char *file)
101: {
102: #ifdef __EMSCRIPTEN__
103:     int w, h;
104:     char *data;
105:     SDL_Surface *surf;
106: 
107:     data = emscripten_get_preloaded_image_data(file, &w, &h);
108:     if (data != NULL) {
109:         surf = SDL_CreateSurface(w, h, SDL_PIXELFORMAT_RGBA32);
110:         if (surf != NULL) {
111:             SDL_memcpy(surf->pixels, data, w * h * 4);
112:         }
113:         free(data); /* This should NOT be SDL_free() */
114:         return surf;
115:     }
116: #endif
117: 
118:     SDL_IOStream *src = SDL_IOFromFile(file, "rb");
119:     if (!src) {
120:         /* The error message has been set in SDL_IOFromFile */
121:         return NULL;
122:     }
123: 
124:     const char *ext = SDL_strrchr(file, '.');
125:     if (ext) {
126:         ext++;
127:     }
128:     return IMG_LoadTyped_IO(src, true, ext);
129: }
130: #endif
