138: /* Load an image from an SDL datasource, optionally specifying the type */
139: SDL_Surface *IMG_LoadTyped_IO(SDL_IOStream *src, bool closeio, const char *type)
140: {
141:     size_t i;
142:     SDL_Surface *image;
143: 
144:     /* Make sure there is something to do.. */
145:     if (!src) {
146:         SDL_InvalidParamError("src");
147:         return NULL;
148:     }
149: 
150:     /* See whether or not this data source can handle seeking */
151:     if (SDL_SeekIO(src, 0, SDL_IO_SEEK_CUR) < 0) {
152:         SDL_SetError("Can't seek in this data source");
153:         if (closeio) {
154:             SDL_CloseIO(src);
155:         }
156:         return NULL;
157:     }
158: 
159: #ifdef __EMSCRIPTEN__
160:     /*load through preloadedImages*/
161:     FILE *fp = (FILE *)SDL_GetPointerProperty(SDL_GetIOProperties(src), SDL_PROP_IOSTREAM_STDIO_FILE_POINTER, NULL);
162:     if (fp) {
163:         int w, h;
164:         char *data;
165: 
166:         data = emscripten_get_preloaded_image_data_from_FILE(fp, &w, &h);
167:         if (data) {
168:             image = SDL_CreateSurface(w, h, SDL_PIXELFORMAT_RGBA32);
169:             if (image != NULL) {
170:                 SDL_memcpy(image->pixels, data, w * h * 4);
171:             }
172:             free(data); /* This should NOT be SDL_free() */
173: 
174:             if (closeio) {
175:                 SDL_CloseIO(src);
176:             }
177: 
178:             /* If SDL_CreateSurface returns NULL, it has set the error message for us */
179:             return image;
180:         }
181:     }
182: #endif
183: 
184:     /* Detect the type of image being loaded */
185:     for (i = 0; i < SDL_arraysize(supported); ++i) {
186:         if (supported[i].is) {
187:             if (!supported[i].is(src)) {
188:                 continue;
189:             }
190:         } else {
191:             /* magicless format */
192:             if (!type || SDL_strcasecmp(type, supported[i].type) != 0) {
193:                 continue;
194:             }
195:         }
196: #ifdef DEBUG_IMGLIB
197:         SDL_Log("IMGLIB: Loading image as %s\n", supported[i].type);
198: #endif
199:         image = supported[i].load(src);
200:         if (closeio) {
201:             SDL_CloseIO(src);
202:         }
203:         return image;
204:     }
205: 
206:     if (closeio) {
207:         SDL_CloseIO(src);
208:     }
209:     SDL_SetError("Unsupported image format");
210:     return NULL;
211: }
