267: /* Load an animation from an SDL datasource, optionally specifying the type */
268: IMG_Animation *IMG_LoadAnimationTyped_IO(SDL_IOStream *src, bool closeio, const char *type)
269: {
270:     size_t i;
271:     IMG_Animation *anim;
272:     SDL_Surface *image;
273: 
274:     /* Make sure there is something to do.. */
275:     if (!src) {
276:         SDL_InvalidParamError("src");
277:         return NULL;
278:     }
279: 
280:     /* See whether or not this data source can handle seeking */
281:     if (SDL_SeekIO(src, 0, SDL_IO_SEEK_CUR) < 0) {
282:         SDL_SetError("Can't seek in this data source");
283:         if (closeio) {
284:             SDL_CloseIO(src);
285:         }
286:         return NULL;
287:     }
288: 
289:     /* Detect the type of image being loaded */
290:     for (i = 0; i < SDL_arraysize(supported_anims); ++i) {
291:         if (supported_anims[i].is) {
292:             if (!supported_anims[i].is(src)) {
293:                 continue;
294:             }
295:         } else {
296:             /* magicless format */
297:             if (!type || SDL_strcasecmp(type, supported_anims[i].type) != 0) {
298:                 continue;
299:             }
300:         }
301: #ifdef DEBUG_IMGLIB
302:         SDL_Log("IMGLIB: Loading image as %s\n", supported_anims[i].type);
303: #endif
304:         anim = supported_anims[i].load(src);
305:         if (closeio) {
306:             SDL_CloseIO(src);
307:         }
308:         return anim;
309:     }
310: 
311:     /* Create a single frame animation from an image */
312:     image = IMG_LoadTyped_IO(src, closeio, type);
313:     if (image) {
314:         anim = (IMG_Animation *)SDL_malloc(sizeof(*anim));
315:         if (anim) {
316:             anim->w = image->w;
317:             anim->h = image->h;
318:             anim->count = 1;
319: 
320:             anim->frames = (SDL_Surface **)SDL_calloc(anim->count, sizeof(*anim->frames));
321:             anim->delays = (int *)SDL_calloc(anim->count, sizeof(*anim->delays));
322:             if (anim->frames && anim->delays) {
323:                 anim->frames[0] = image;
324:                 return anim;
325:             }
326:             IMG_FreeAnimation(anim);
327:         }
328:         SDL_DestroySurface(image);
329:     }
330:     return NULL;
331: }
