371: bool IMG_SaveTyped_IO(SDL_Surface *surface, SDL_IOStream *dst, bool closeio, const char *type)
372: {
373:     bool result = false;
374: 
375:     if (!surface) {
376:         SDL_InvalidParamError("surface");
377:         goto done;
378:     }
379: 
380:     if (!dst) {
381:         SDL_InvalidParamError("dst");
382:         goto done;
383:     }
384: 
385:     if (!type || !*type) {
386:         SDL_InvalidParamError("type");
387:         goto done;
388:     }
389: 
390:     if (SDL_strcasecmp(type, "avif") == 0) {
391:         result = IMG_SaveAVIF_IO(surface, dst, false, 90);
392:     } else if (SDL_strcasecmp(type, "bmp") == 0) {
393:         result = IMG_SaveBMP_IO(surface, dst, false);
394:     } else if (SDL_strcasecmp(type, "cur") == 0) {
395:         result = IMG_SaveCUR_IO(surface, dst, false);
396:     } else if (SDL_strcasecmp(type, "gif") == 0) {
397:         result = IMG_SaveGIF_IO(surface, dst, false);
398:     } else if (SDL_strcasecmp(type, "ico") == 0) {
399:         result = IMG_SaveICO_IO(surface, dst, false);
400:     } else if (SDL_strcasecmp(type, "jpg") == 0 ||
401:                SDL_strcasecmp(type, "jpeg") == 0) {
402:         result = IMG_SaveJPG_IO(surface, dst, false, 90);
403:     } else if (SDL_strcasecmp(type, "png") == 0) {
404:         result = IMG_SavePNG_IO(surface, dst, false);
405:     } else if (SDL_strcasecmp(type, "tga") == 0) {
406:         result = IMG_SaveTGA_IO(surface, dst, false);
407:     } else if (SDL_strcasecmp(type, "webp") == 0) {
408:         result = IMG_SaveWEBP_IO(surface, dst, false, 90.0f);
409:     } else {
410:         result = SDL_SetError("Unsupported image format");
411:     }
412: 
413: done:
414:     if (dst && closeio) {
415:         result &= SDL_CloseIO(dst);
416:     }
417:     return result;
418: }
