486: SDL_Surface *IMG_GetClipboardImage(void)
487: {
488:     SDL_Surface *surface = NULL;
489: 
490:     char **mime_types = SDL_GetClipboardMimeTypes(NULL);
491:     if (mime_types) {
492:         for (int i = 0; !surface && mime_types[i]; ++i) {
493:             if (SDL_strncmp(mime_types[i], "image/", 6) == 0) {
494:                 size_t size = 0;
495:                 void *data = SDL_GetClipboardData(mime_types[i], &size);
496:                 if (data) {
497:                     SDL_IOStream *src = SDL_IOFromConstMem(data, size);
498:                     if (src) {
499:                         surface = IMG_Load_IO(src, true);
500:                     }
501:                     SDL_free(data);
502:                 }
503:             }
504:         }
505:     }
506:     if (!surface) {
507:         SDL_SetError("No clipboard image available");
508:     }
509:     return surface;
510: }
