512: SDL_Cursor *IMG_CreateAnimatedCursor(IMG_Animation *anim, int hot_x, int hot_y)
513: {
514:     int i;
515:     SDL_CursorFrameInfo *frames;
516:     SDL_Cursor *cursor;
517: 
518:     if (!anim) {
519:         SDL_InvalidParamError("anim");
520:         return NULL;
521:     }
522: 
523:     frames = (SDL_CursorFrameInfo *)SDL_calloc(anim->count, sizeof(*frames));
524:     if (!frames) {
525:         return NULL;
526:     }
527: 
528:     for (i = 0; i < anim->count; ++i) {
529:         frames[i].surface = anim->frames[i];
530:         frames[i].duration = (Uint32)anim->delays[i];
531:     }
532: 
533:     cursor = SDL_CreateAnimatedCursor(frames, anim->count, hot_x, hot_y);
534: 
535:     SDL_free(frames);
536: 
537:     return cursor;
