566: SDL_Surface *IMG_ApplyOrientation(SDL_Surface *surface, int orientation)
567: {
568:     float rotation = 0.0f;
569:     SDL_FlipMode flip = SDL_FLIP_NONE;
570:     switch (orientation) {
571:     case 1:
572:         // Normal (no rotation required)
573:         break;
574:     case 2:
575:         // Mirror horizontal
576:         flip = SDL_FLIP_HORIZONTAL;
577:         break;
578:     case 3:
579:         // Rotate 180
580:         rotation = 180.0f;
581:         break;
582:     case 4:
583:         // Mirror vertical
584:         flip = SDL_FLIP_VERTICAL;
585:         break;
586:     case 5:
587:         // Mirror horizontal and rotate 270 CW
588:         flip = SDL_FLIP_HORIZONTAL;
589:         rotation = 270.0f;
590:         break;
591:     case 6:
592:         // Rotate 90 CW
593:         rotation = 90.0f;
594:         break;
595:     case 7:
596:         // Mirror horizontal and rotate 90 CW
597:         flip = SDL_FLIP_HORIZONTAL;
598:         rotation = 90.0f;
599:         break;
600:     case 8:
601:         // Rotate 270 CW
602:         rotation = 270.0f;
603:         break;
604:     default:
605:         break;
606:     }
607: 
608: #ifdef ORIENTATION_USES_PROPERTIES
