216:     CGImageAlphaInfo alpha = CGImageGetAlphaInfo(image_ref);
217:     //size_t bits_per_pixel = CGImageGetBitsPerPixel(image_ref);
218:     size_t bits_per_component = 8;
219: 
220:     SDL_Surface* surface;
221:     Uint32 format;
222: 
223:     CGContextRef bitmap_context;
224:     CGBitmapInfo bitmap_info;
225:     CGColorSpaceRef color_space = CGColorSpaceCreateDeviceRGB();
226: 
227:     if (alpha == kCGImageAlphaNone ||
228:         alpha == kCGImageAlphaNoneSkipFirst ||
229:         alpha == kCGImageAlphaNoneSkipLast) {
230:         bitmap_info = kCGImageAlphaNoneSkipFirst | kCGBitmapByteOrder32Host; /* XRGB */
231:         format = SDL_PIXELFORMAT_XRGB8888;
232:     } else {
233:         /* kCGImageAlphaFirst isn't supported */
234:         //bitmap_info = kCGImageAlphaFirst | kCGBitmapByteOrder32Host; /* ARGB */
235:         bitmap_info = kCGImageAlphaPremultipliedFirst | kCGBitmapByteOrder32Host; /* ARGB */
236:         format = SDL_PIXELFORMAT_ARGB8888;
237:     }
238: 
239:     surface = SDL_CreateSurface((int)w, (int)h, format);
240:     if (surface)
241:     {
242:         // Sets up a context to be drawn to with surface->pixels as the area to be drawn to
243:         bitmap_context = CGBitmapContextCreate(
244:                                                surface->pixels,
245:                                                surface->w,
246:                                                surface->h,
247:                                                bits_per_component,
248:                                                surface->pitch,
249:                                                color_space,
250:                                                bitmap_info
251:                                                );
252: 
253:         // Draws the image into the context's image_data
254:         CGContextDrawImage(bitmap_context, rect, image_ref);
255: 
256:         CGContextRelease(bitmap_context);
257: 
258:         // FIXME: Reverse the premultiplied alpha
259:         if ((bitmap_info & kCGBitmapAlphaInfoMask) == kCGImageAlphaPremultipliedFirst) {
260:             int i, j;
261:             Uint8 *p = (Uint8 *)surface->pixels;
262:             for (i = surface->h * surface->pitch/4; i--; ) {
263: #if __LITTLE_ENDIAN__
264:                 Uint8 A = p[3];
265:                 if (A) {
266:                     for (j = 0; j < 3; ++j) {
267:                         p[j] = (p[j] * 255) / A;
268:                     }
269:                 }
270: #else
271:                 Uint8 A = p[0];
272:                 if (A) {
273:                     for (j = 1; j < 4; ++j) {
274:                         p[j] = (p[j] * 255) / A;
275:                     }
276:                 }
277: #endif /* ENDIAN */
278:                 p += 4;
279:             }
280:         }
281:     }
