290: static SDL_Surface* Create_SDL_Surface_From_CGImage_Index(CGImageRef image_ref)
291: {
292:     size_t w = CGImageGetWidth(image_ref);
293:     size_t h = CGImageGetHeight(image_ref);
294:     size_t bits_per_pixel = CGImageGetBitsPerPixel(image_ref);
295:     size_t bytes_per_row = CGImageGetBytesPerRow(image_ref);
296: 
297:     SDL_Surface* surface;
298:     CGColorSpaceRef color_space = CGImageGetColorSpace(image_ref);
299:     CGColorSpaceRef base_color_space = CGColorSpaceGetBaseColorSpace(color_space);
300:     size_t num_components = CGColorSpaceGetNumberOfComponents(base_color_space);
301:     size_t num_entries = CGColorSpaceGetColorTableCount(color_space);
302:     uint8_t *entry, *entries;
303: 
304:     entries = SDL_stack_alloc(uint8_t, num_components * num_entries);
305: 
306:     if (entries == NULL) {
307:         SDL_OutOfMemory();
308:         return NULL;
309:     }
310: 
311:     /* What do we do if it's not RGB? */
312:     if (num_components != 3) {
313:         SDL_SetError("Unknown colorspace components %lu", num_components);
314:         return NULL;
315:     }
316:     if (bits_per_pixel != 8) {
317:         SDL_SetError("Unknown bits_per_pixel %lu", bits_per_pixel);
318:         return NULL;
319:     }
320: 
321:     CGColorSpaceGetColorTable(color_space, entries);
322:     surface = SDL_CreateSurface((int)w, (int)h, SDL_PIXELFORMAT_INDEX8);
323:     if (surface) {
324:         uint8_t* pixels = (uint8_t*)surface->pixels;
325:         CGDataProviderRef provider = CGImageGetDataProvider(image_ref);
326:         NSData* data = (id)CGDataProviderCopyData(provider);
327:         [data autorelease];
328:         const uint8_t* bytes = [data bytes];
329:         size_t i;
330: 
331:         if (num_entries > 0) {
332:             SDL_Palette* palette = SDL_CreateSurfacePalette(surface);
333:             if (palette) {
334:                 if (num_entries > (size_t)palette->ncolors) {
335:                     num_entries = (size_t)palette->ncolors;
336:                 }
337:                 palette->ncolors = (int)num_entries;
338:                 for (i = 0, entry = entries; i < num_entries; ++i) {
339:                     palette->colors[i].r = entry[0];
340:                     palette->colors[i].g = entry[1];
341:                     palette->colors[i].b = entry[2];
342:                     palette->colors[i].a = SDL_ALPHA_OPAQUE;
343:                     entry += num_components;
344:                 }
345:             }
346:         }
347: 
348:         for (i = 0; i < h; ++i) {
349:             SDL_memcpy(pixels, bytes, w);
350:             pixels += surface->pitch;
351:             bytes += bytes_per_row;
352:         }
353:     }
354: 
355:     SDL_stack_free(entries);
356: 
357:     return surface;
358: }
