381: static bool Internal_isType (SDL_IOStream *rw_ops, CFStringRef uti_string_to_test)
382: {
383:     bool is_type = false;
384: 
385:     if (rw_ops == NULL) {
386:         return false;
387:     }
388: 
389:     Sint64 start = SDL_TellIO(rw_ops);
390:     CGImageSourceRef image_source = CreateCGImageSourceFromIOStream(rw_ops, NULL);
391: 
392:     if (NULL == image_source) {
393:         // reset the file pointer
394:         SDL_SeekIO(rw_ops, start, SEEK_SET);
395:         return 0;
396:     }
397: 
398:     // This will get the UTI of the container, not the image itself.
399:     // Under most cases, this won't be a problem.
400:     // But if a person passes an icon file which contains a bmp,
401:     // the format will be of the icon file.
402:     // But I think the main SDL_image codebase has this same problem so I'm not going to worry about it.
403:     CFStringRef uti_type = CGImageSourceGetType(image_source);
404:     //  CFShow(uti_type);
405: 
406:     // Unsure if we really want conformance or equality
407:     is_type = UTTypeConformsTo(uti_string_to_test, uti_type);
408: 
409:     CFRelease(image_source);
410: 
411:     // reset the file pointer
412:     SDL_SeekIO(rw_ops, start, SEEK_SET);
413:     return is_type;
414: }
