566:     char *ext = SDL_strrchr(file, '.');
567:     if (ext) {
568:         ext++;
569:     }
570: 
571:     if (ext && (SDL_strcasecmp(ext, "ico") == 0 || SDL_strcasecmp(ext, "cur") == 0)) {
572:         /* CreateCGImageSourceFromFile() doesn't detect the correct format, skip it */
573:     } else {
574:         surface = LoadImageFromFile(file);
